11	const Kpi = ({ icon, label, value, sub, color = 'gray' }) => {
12	  const colors = {
13	    green: 'border-green-200 bg-green-50',
14	    blue:  'border-blue-200 bg-blue-50',
15	    amber: 'border-amber-200 bg-amber-50',
16	    red:   'border-red-200 bg-red-50',
17	    gray:  'border-[#E4E4E7] bg-white',
