19	  const txt = { green: 'text-green-700', blue: 'text-blue-700', amber: 'text-amber-700', red: 'text-red-600', gray: 'text-[#18181B]' };
20	  return (
21	    <div className={`rounded-xl border p-3 ${colors[color]}`}>
22	      <div className="flex items-center gap-1.5 mb-1">
23	        <Icon name={icon} size={13} className={txt[color]} />
24	        <p className="text-[10px] font-bold uppercase tracking-widest text-[#71717A]">{label}</p>
25	      </div>
