38	
39	  return (
40	    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
41	      <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
42	        <div className="text-center mb-4">
43	          <p className="text-2xl mb-1">{isSaida ? '💸' : '💰'}</p>
44	          <h2 className="text-base font-bold text-[#18181B]">{isSaida ? 'Sangria (Retirada)' : 'Adição de Dinheiro'}</h2>
