84	// lista PLANA por item (não agrupa por mesa/comanda), com cronômetro de espera/preparo.
85	const RestauranteProducao = () => {
86	  const navigate = useNavigate();
87	  const [impressoras, setImpressoras] = useState(null);
88	  const [itensPorImpressora, setItensPorImpressora] = useState({});
89	  const [restauranteNome, setRestauranteNome] = useState('');
90	  const [loading, setLoading] = useState(true);
91	  const [erro, setErro] = useState(null);
92	  const [lastUpdate, setLastUpdate] = useState(null);
93	  const now = useNowTick();
94	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
95	  const prevItemIds = useRef(new Set());
96	  const firstLoad = useRef(true);
97	  const tocarSom = useNotificacaoSonora('cozinha');
98	
99	  useEffect(() => {
100	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
101	    listarImpressoras().then(setImpressoras).catch((e) => setErro(e.message));
102	  }, []);
103	
104	  const carregar = useCallback(async (lista) => {
105	    try {
106	      const resultados = await Promise.all(
107	        lista.map((imp) => getKdsItensRestaurante(imp.id).then((r) => [imp, r.itens ?? []])),
108	      );
109	      const porImpressora = {};
110	      const idsAgora = new Set();
111	      for (const [imp, itens] of resultados) {
112	        porImpressora[imp.id] = itens;
113	        for (const i of itens) idsAgora.add(i.id);
114	      }
115	
116	      if (!firstLoad.current) {
117	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
118	        if (novos.length > 0) tocarSom();
119	      } else {
120	        firstLoad.current = false;
121	      }
122	      prevItemIds.current = idsAgora;
123	
124	      setItensPorImpressora(porImpressora);
125	      setLastUpdate(new Date());
126	      setErro(null);
127	    } catch (e) {
128	      setErro(e.message);
129	    } finally {
130	      setLoading(false);
131	    }
132	  }, [tocarSom]);
133	
134	  useEffect(() => {
135	    if (!impressoras) return;
136	    if (impressoras.length === 0) { setLoading(false); return; }
137	    carregar(impressoras);
138	    const interval = setInterval(() => carregar(impressoras), 15000);
139	    return () => clearInterval(interval);
140	  }, [impressoras, carregar]);
141	
142	  const marcarPronto = async (itemId) => {
143	    await marcarItemProntoRestaurante(itemId);
144	    carregar(impressoras);
145	  };
146	
147	  const iniciarPreparo = async (item) => {
148	    await iniciarPreparoItemRestaurante(item.id);
149	    carregar(impressoras);
150	  };
151	
152	  const reimprimir = async (item, setorNome) => {
153	    try {
154	      const res = await reimprimirItemRestaurante(item.id);
155	      if (res.via === 'navegador') {
156	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente }, setorNome);
157	      }
158	    } catch (e) {
159	      setErro(e.message);
160	    }
161	  };
162	
163	  if (loading) return (
164	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
165	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
166	    </div>
167	  );
168	
169	  const todosItens = Object.values(itensPorImpressora).flat();
170	  const totalDelivery = todosItens.filter((i) => i.tipo === 'delivery').length;
171	  const totalSalao = todosItens.filter((i) => i.tipo === 'salao').length;
172	  const passaFiltro = (i) => filtroCanal === 'todos' || i.tipo === filtroCanal;
173	  const totalItens = todosItens.filter(passaFiltro).length;
174	
175	  return (
176	    <div className="min-h-screen bg-[#111111]">
177	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
178	        <div className="flex items-center gap-4">
179	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
180	            <Icon name="ArrowLeft" size={18} />
181	          </button>
