188	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
189	            </div>
190	          </div>
191	          <div className="ml-auto flex items-center gap-2">
192	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
193	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
194	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
195	            </div>
196	            <button onClick={() => carregar(impressoras ?? [])} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
197	              <Icon name="RefreshCw" size={16} />
198	            </button>
199	          </div>
200	        </div>
