    subtotal += totalItem;
    linhas.push(this.removerAcentos(`${item.quantity}x ${item.product_name ?? 'Produto'}`));
    linhas.push(`R$ ${fmt(totalItem)}`);
  }
  linhas.push('--------------------------------');
