import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { listarImpressoras, getKdsItensRestaurante, marcarItemProntoRestaurante, reimprimirItemRestaurante, iniciarPreparoItemRestaurante, voltarStatusItemRestaurante, getMinhaEmpresa } from '../../services/restauranteService';
import { printTicketSetor } from '../../utils/printComanda';
import { formatDuracao } from '../../utils/formatDuracao';
import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
import { useNowTick } from '../../hooks/useNowTick';
import Icon from '../../components/AppIcon';

// Card por item (não por mesa/comanda) com cronômetro ao vivo — mostra há quanto tempo
// o item chegou (aguardando) e, quando em preparo, há quanto tempo está preparando,
// pra dar visibilidade do tempo total gasto até ficar pronto.
const ItemCard = ({ item, posicao, now, onReimprimir, onIniciarPreparo, onMarcarPronto, onVoltar }) => {
  const enviadoEm = new Date(item.enviado_em).getTime();
  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
  const tempoTotal = now - enviadoEm;

  return (
    <div className={`bg-[#1A1A1A] border rounded-2xl p-4 ${posicao === 1 ? 'border-yellow-400/70 ring-1 ring-yellow-400/30' : item.status === 'enviado' ? 'border-blue-500/40' : 'border-[#2A2A2A]'}`}>
      <div className="flex items-start justify-between mb-1 gap-2">
        <div className="flex items-start gap-2">
          <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${posicao === 1 ? 'bg-yellow-400 text-black' : 'bg-[#2A2A2A] text-white'}`}>
            {posicao}
          </span>
          <div className="leading-tight">
            <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
            <p className="text-lg font-bold text-white">Produto: {item.product_name}</p>
          </div>
        </div>
        <button onClick={() => onReimprimir(item)}
          className="text-[10px] font-bold text-orange-400 border border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
          <Icon name="Printer" size={11} /> Reimpressão
        </button>
      </div>
      {posicao === 1 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
      {item.observacao && <p className="text-xs text-amber-400 mb-1">Obs: {item.observacao}</p>}
      <div className="flex items-center gap-2 text-xs text-[#71717A] mb-2">
        <Icon name="MapPin" size={12} />
        <span>{item.mesa ?? item.cliente ?? (item.tipo === 'delivery' ? `Pedido #${item.order_id}` : 'Avulsa')}</span>
        {item.numero_comanda && (
          <>
            <span className="text-[#3A3A3A]">•</span>
            <span>Comanda #{item.numero_comanda}</span>
          </>
        )}
        {item.garcom && (
          <>
            <span className="text-[#3A3A3A]">•</span>
            <Icon name="User" size={12} />
            <span>{item.garcom}</span>
          </>
        )}
        <span className={`ml-auto px-1.5 py-0.5 rounded-full text-[10px] font-bold ${item.tipo === 'delivery' ? 'bg-sky-500/20 text-sky-400' : 'bg-purple-500/20 text-purple-300'}`}>
          {item.tipo === 'delivery' ? 'Delivery' : 'Salão'}
        </span>
      </div>
      <div className="flex items-center gap-3 text-[11px] font-mono mb-3">
        <span className="flex items-center gap-1 text-blue-400">
          <Icon name="Clock" size={11} /> espera {formatDuracao(tempoEspera)}
        </span>
        {item.status === 'preparando' && (
          <span className="flex items-center gap-1 text-orange-400">
            <Icon name="Flame" size={11} /> preparo {formatDuracao(tempoPreparo)}
          </span>
        )}
        <span className="ml-auto text-[#71717A]">total {formatDuracao(tempoTotal)}</span>
      </div>
      <div className="flex gap-2">
        {item.status !== 'enviado' && (
          <button onClick={() => onVoltar(item)} title="Desfazer — clicou errado"
            className="flex-shrink-0 px-3 py-2 bg-[#2A2A2A] hover:bg-[#3A3A3A] text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
            <Icon name="Undo2" size={13} /> Voltar
          </button>
        )}
        {item.status === 'enviado' ? (
          <button onClick={() => onIniciarPreparo(item)}
            className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
            <Icon name="ChefHat" size={13} /> Iniciar Preparo
          </button>
        ) : item.status === 'pronto' ? (
          <div className="flex-1 py-2 bg-emerald-900/40 text-emerald-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
            <Icon name="Check" size={13} /> {item.entregue_garcom ? 'Entregue pelo garçom' : 'Entregue'}
          </div>
        ) : (
          <button onClick={() => onMarcarPronto(item.id)}
            className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
            <Icon name="Check" size={13} /> Pronto
          </button>

const SalaoItemCard = ({ item, posicao, now, onReimprimir, onIniciarPreparo, onMarcarPronto, onVoltar }) => {
  const enviadoEm = new Date(item.enviado_em).getTime();
  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
  const tempoTotal = now - enviadoEm;

  return (
  <div className={`rounded-2xl border-2 overflow-hidden ${posicao === 1 ? 'border-yellow-400/70 bg-purple-950/20 ring-1 ring-yellow-400/30' : 'border-purple-300 bg-purple-950/20'}`}>
    {item.garcom && (
      <div className="bg-white px-4 py-2">
        <p className="text-center text-lg font-black text-[#18181B] uppercase tracking-wide">{item.garcom}</p>
      </div>
    )}
    <div className="p-4">
    <div className="flex items-start justify-between mb-1 gap-2">
      <div className="flex items-start gap-2">
        <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${posicao === 1 ? 'bg-yellow-400 text-black' : 'bg-purple-900/50 text-white'}`}>
          {posicao}
        </span>
        <div className="leading-tight">
          <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
          <p className="text-lg font-bold text-white">Produto: {item.product_name} <span className="text-purple-300 font-normal text-xs">· Salão</span></p>
        </div>
      </div>
      <button onClick={() => onReimprimir(item)}
        className="text-[10px] font-bold text-orange-400 border border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
        <Icon name="Printer" size={11} /> Reimpressão
      </button>
    </div>
    {posicao === 1 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
    {item.observacao && <p className="text-sm font-bold text-white bg-blue-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">Obs: {item.observacao}</p>}
    <div className="flex items-center gap-2 text-base font-bold text-yellow-400 mb-2">
      <Icon name="MapPin" size={14} />
      <span>{item.mesa ?? item.cliente ?? 'Avulsa'}</span>
    </div>
    <div className="flex items-center gap-3 text-[11px] font-mono mb-3">
      <span className="flex items-center gap-1 text-blue-400">
        <Icon name="Clock" size={11} /> espera {formatDuracao(tempoEspera)}
      </span>
      {item.status === 'preparando' && (
        <span className="flex items-center gap-1 text-orange-400">
          <Icon name="Flame" size={11} /> preparo {formatDuracao(tempoPreparo)}
        </span>
      )}
      <span className="ml-auto text-[#71717A]">total {formatDuracao(tempoTotal)}</span>
    </div>
    <div className="flex gap-2">
      {item.status !== 'enviado' && (
        <button onClick={() => onVoltar(item)} title="Desfazer — clicou errado"
          className="flex-shrink-0 px-3 py-2 bg-purple-900/40 hover:bg-purple-900/60 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
          <Icon name="Undo2" size={13} /> Voltar
        </button>
      )}
      {item.status === 'enviado' && (
        <button onClick={() => onIniciarPreparo(item)}
          className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
          <Icon name="ChefHat" size={13} /> Iniciar Preparo
        </button>
      )}
      {item.status === 'preparando' && (
        <button onClick={() => onMarcarPronto(item.id)}
          className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
          <Icon name="Check" size={13} /> Pronto
        </button>
      )}
      {item.status === 'pronto' && (
        <div className="flex-1 py-2 bg-emerald-900/40 text-emerald-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
          <Icon name="Check" size={13} /> Pronto
        </div>
      )}
    </div>
    </div>
  </div>
  );

        ) : (
          <button onClick={() => onMarcarPronto(item.id)}
            className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
            <Icon name="Check" size={13} /> Pronto
          </button>
        )}
      </div>
    </div>
  );
};

// Linha de produção do Salão — visão unificada de TODOS os setores (cozinha, bar,
// salgados...) num painel só, dono acessa direto logado (sem link/token separado, mesmo
// padrão de acesso da tela de Cozinha do delivery). Cada setor é uma impressora
// cadastrada; itens vêm de order_items roteados pra ela (ver GET /restaurante/kds),

      {itens.length}
    </span>
  )}
</div>
{itens.length === 0 ? (
  <div className="rounded-2xl border-2 border-dashed border-[#2A2A2A] p-6 text-center mb-2">
    <p className="text-[#71717A] text-sm">Nenhum item pendente em {imp.setor}</p>
  </div>
) : (
  <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
    <div>
      <p className="text-xs font-bold text-blue-400 uppercase tracking-wider mb-2">Aguardando Preparo</p>
      {aguardando.length === 0 ? (
        <p className="text-xs text-[#71717A]">Nenhum</p>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
          {aguardando.map((item, idx) => (
            <ItemCard key={item.id} item={item} posicao={idx + 1} now={now}
              onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} />
          ))}
        </div>
      )}
    </div>
    <div>
      <p className="text-xs font-bold text-orange-400 uppercase tracking-wider mb-2">Em Preparo</p>

