451	    const origem = await this.buscarComanda(origemId, restaurantId);
452	    if (!['aberta', 'fechada_garcom'].includes(origem.status)) {
453	      throw new BadRequestException('Só é possível transferir comandas abertas ou aguardando pagamento');
454	    }
455	
456	    let destinoId = params.comanda_destino_id ?? null;
457	
458	    if (params.mesa_id) {
459	      const { data: mesaDestino } = await this.supabase.client
460	        .from('mesas')
461	        .select('id, status')
462	        .eq('id', params.mesa_id)
463	        .eq('restaurant_id', restaurantId)
464	        .maybeSingle();
465	      if (!mesaDestino) throw new NotFoundException('Mesa de destino não encontrada');
